export default function Home() {
  return (
    <div className="home">
      <h2>Welcome</h2>
      <p>
        Welcome to Job Router, a simple place to explore job opportunities and
        navigate through different career paths. Whether you are looking for
        your first role, practicing your routing skills, or building a better
        React project, this app helps organize job pages in a clean and easy
        way. Start browsing, add new posts, and keep moving toward your next
        opportunity.
      </p>
    </div>
  );
}
